    32  /* Delayed callbacks are executed when all previously enqueue work is finished.
    33   * This is used to free memory that might used by a parallel worker or where the
    34   * current threat has remaining pointers to until the current operation
    35   * finishes. */
    36  typedef struct UA_DelayedCallback {
    37      SIMPLEQ_ENTRY(UA_DelayedCallback) next;
    38      UA_ApplicationCallback callback;
    39      void *application;
    40      void *data;
    41  } UA_DelayedCallback;
