    48  /* Workers take out callbacks from the work queue and execute them.
    49   *
    50   * Future Plans: Use work-stealing to load-balance between cores.
    51   * Le, Nhat Minh, et al. "Correct and efficient work-stealing for weak memory
    52   * models." ACM SIGPLAN Notices. Vol. 48. No. 8. ACM, 2013. */
    53  typedef struct {
    54      pthread_t thread;
    55      volatile UA_Boolean running;
    56      UA_WorkQueue *queue;
    57      UA_UInt32 counter;
    58      UA_UInt32 checkpointCounter; /* Counter when the last checkpoint was made
    59                                    * for the delayed callbacks */
    60
    61      /* separate cache lines */
    62      char padding[64 - sizeof(void*) - sizeof(pthread_t) -
    63                   sizeof(UA_UInt32) - sizeof(UA_Boolean)];
    64  } UA_Worker;
    65
    66  #endif
