    68  struct UA_WorkQueue {
    69      /* Worker threads and work queue. Without multithreading, work is executed
    70         immediately. */
    71  #ifdef UA_ENABLE_MULTITHREADING
    72      UA_Worker *workers;
    73      size_t workersSize;
    74
    75      /* Work queue */
    76      SIMPLEQ_HEAD(, UA_DelayedCallback) dispatchQueue; /* Dispatch queue for the worker threads */
    77      pthread_mutex_t dispatchQueue_accessMutex; /* mutex for access to queue */
    78      pthread_cond_t dispatchQueue_condition; /* so the workers don't spin if the queue is empty */
    79      pthread_mutex_t dispatchQueue_conditionMutex; /* mutex for access to condition variable */
    80  #endif
    81
    82      /* Delayed callbacks
    83       * To be executed after all curretly dispatched works has finished */
    84      SIMPLEQ_HEAD(, UA_DelayedCallback) delayedCallbacks;
    85  #ifdef UA_ENABLE_MULTITHREADING
    86      pthread_mutex_t delayedCallbacks_accessMutex;
    87      UA_DelayedCallback *delayedCallbacks_checkpoint;
    88      size_t delayedCallbacks_sinceDispatch; /* How many have been added since we
    89                                              * tried to dispatch callbacks? */
    90  #endif
    91  };
